package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_deserialize_TriageGen1Test {

    private StringArrayDeserializer deserializer;

    @Mock
    private JsonParser jp;

    @Mock
    private DeserializationContext ctxt;

    @Mock
    private ObjectBuffer buffer;

    @Mock
    private com.fasterxml.jackson.databind.JsonDeserializer _elementDeserializer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.initMocks(this);
        deserializer = new StringArrayDeserializer();

        // Inject the mock element deserializer via reflection since it's a private field
        Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        field.set(deserializer, _elementDeserializer);
    }

    @Test
    public void testDeserialize_NonArrayToken() throws IOException {
        // Mock handleNonArray via a spy or by testing the branch
        // Since handleNonArray is protected, we trigger the branch where isExpectedStartArrayToken is false
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        when(jp.isExpectedStartArrayToken()).thenReturn(false);
        when(spyDeserializer.handleNonArray(jp, ctxt)).thenReturn(new String[]{"not-an-array"});

        String[] result = spyDeserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"not-an-array"}, result);
        verify(spyDeserializer).handleNonArray(jp, ctxt);
    }

    @Test
    public void testDeserialize_CustomDeserializerPresent() throws IOException {
        // If _elementDeserializer is not null, it calls _deserializeCustom
        // In our setup, it is not null.
        when(jp.isExpectedStartArrayToken()).thenReturn(true);

        StringArrayDeserializer spyDeserializer = spy(deserializer);
        String[] expected = {"custom"};
        doReturn(expected).when(spyDeserializer)._deserializeCustom(jp, ctxt);

        String[] result = spyDeserializer.deserialize(jp, ctxt);

        assertArrayEquals(expected, result);
        verify(spyDeserializer)._deserializeCustom(jp, ctxt);
    }

    @Test
    public void testDeserialize_StandardArrayWithMixedTokens() throws IOException {
        // To test the main logic, we need _elementDeserializer to be null for the custom branch, 
        // BUT the code uses _elementDeserializer.getNullValue() if token is VALUE_NULL.
        // This implies if _elementDeserializer is null, the code would NPE on VALUE_NULL.
        // However, the logic flow says if _elementDeserializer != null, it goes to _deserializeCustom.
        // To reach the while loop, _elementDeserializer MUST be null.
        // To avoid NPE on VALUE_NULL, we must ensure no VALUE_NULL tokens are passed if it's null.

        Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        field.set(deserializer, null);

        when(jp.isExpectedStartArrayToken()).thenReturn(true);
        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);

        // Mock buffer behavior
        Object[] initialChunk = new Object[1];
        when(buffer.resetAndStart()).thenReturn(initialChunk);
        when(buffer.appendCompletedChunk(any())).thenReturn(new Object[2]);
        when(buffer.completeAndClearBuffer(any(), anyInt(), eq(String.class))).thenReturn(new String[]{"a", "b"});

        // Token sequence: START_ARRAY (handled by isExpectedStartArrayToken), then VALUE_STRING, VALUE_STRING, END_ARRAY
        // Note: jp.nextToken() is called inside the loop.
        when(jp.nextToken())
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.END_ARRAY);

        when(jp.getText()).thenReturn("a").thenReturn("b");

        String[] result = deserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"a", "b"}, result);
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserialize_ArrayWithChunkOverflow() throws IOException {
        Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        field.set(deserializer, null);

        when(jp.isExpectedStartArrayToken()).thenReturn(true);
        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);

        Object[] chunk1 = new Object[1];
        Object[] chunk2 = new Object[1];
        when(buffer.resetAndStart()).thenReturn(chunk1);
        when(buffer.appendCompletedChunk(any())).thenReturn(chunk2);
        when(buffer.completeAndClearBuffer(any(), anyInt(), eq(String.class))).thenReturn(new String[]{"1", "2"});

        // 1st call: VALUE_STRING ("1")
        // 2nd call: VALUE_STRING ("2") -> this triggers ix >= chunk.length (1 >= 1)
        // 3rd call: END_ARRAY
        when(jp.nextToken())
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.END_ARRAY);

        when(jp.getText()).thenReturn("1").thenReturn("2");

        String[] result = deserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"1", "2"}, result);
        verify(buffer).appendCompletedChunk(chunk1);
    }

    @Test
    public void testDeserialize_ValueNullBranch() throws IOException {
        // To test the VALUE_NULL branch, _elementDeserializer must NOT be null.
        // But if it's not null, it goes to _deserializeCustom.
        // This suggests the code structure assumes if _elementDeserializer is null, 
        // it won't encounter VALUE_NULL, or the code provided has a logical dependency.
        // Let's test the _deserializeCustom path to cover the null check logic in the loop if possible,
        // but based on the provided code, if _elementDeserializer != null, we never enter the loop.

        // Therefore, we test the _deserializeCustom path via a spy.
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        when(jp.isExpectedStartArrayToken()).thenReturn(true);
        when(spyDeserializer._elementDeserializer != null).thenReturn(true); // Logic check

        // Since we can't easily change the if condition without changing the field,
        // and the field is already set in setUp, we call deserialize.
        // It will hit _deserializeCustom.

        String[] expected = {"null-test"};
        doReturn(expected).when(spyDeserializer)._deserializeCustom(jp, ctxt);

        String[] result = spyDeserializer.deserialize(jp, ctxt);
        assertArrayEquals(expected, result);
    }
}
